recipes.code:
{
  "inputs": [
    {
      "id": "settle-api-key",
      "type": "promptString",
      "description": "SettleMesh API key (sk-settle-...). Optional if you have run `settlemesh login` and a CLI session is stored. Never written to the protocol stream or logs.",
      "password": true
    }
  ],
  "servers": {
    "cli": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "mcp",
        "settlemesh@0.1.92"
      ],
      "env": {
        "SETTLE_API_KEY": "${input:settle-api-key}"
      }
    }
  }
}
